func check(_ condition: @autoclosure () -> Bool, _ message: String) { precondition(condition(), message) }
let a = Account(18201, 182001), b = Account(18202, 182002), bot = Account(18203, 182003, bot: true)
let sa = JerkgramLocalAppearanceStore(account: a, clock: { wall })
let sb = JerkgramLocalAppearanceStore(account: b, clock: { wall })
let sx = JerkgramLocalAppearanceStore(account: bot, clock: { wall })
func projected(_ store: JerkgramLocalAppearanceStore, _ user: TelegramUser) -> TelegramUser {
    guard case let .user(result)? = store.project(.user(user)) else { preconditionFailure() }; return result
}
UserDefaults.standard.set(true, forKey: JerkgramAppIconAccess.preferenceKey)
JerkgramLocalPremiumPolicy.update(masterEnabled: false)
JerkgramDownloadBoostSettings.update(accountPeerId: a.peerId.toInt64(), rawValue: "maximum")
JerkgramSponsoredContentPolicy.update(accountPeerId: a.peerId.toInt64(), enabled: true)
JerkgramTranslationSettings.update(accountPeerId: a.peerId.toInt64(), enabled: true)
JerkgramLocalPremiumPolicy.updateTags(accountPeerId: a.peerId.toInt64(), enabled: true)
sa.setActive(true)
check(sa.update { $0.emojiEnabled = true; $0.emojiFileId = 77; $0.colorsEnabled = true; $0.profileColor = 5 }, "save independent choices with master off")
let saved = sa.snapshot.settings
check(projected(sa, a.postbox.user).emojiStatus == nil, "master off uses native peer")
check(JerkgramDownloadBoostSettings.mode(accountPeerId: a.peerId.toInt64()) == .off, "master off actual boost accessor")
check(!JerkgramSponsoredContentPolicy.removeSponsored(accountPeerId: a.peerId.toInt64()), "master off stock sponsored")
check(!JerkgramTranslationSettings.enabled(accountPeerId: a.peerId.toInt64()), "master off translation")
check(!JerkgramLocalPremiumPolicy.savedTagsEnabled(accountPeerId: a.peerId.toInt64()), "master off tags")
check(JerkgramAppIconAccess.isLocked(iconIsPremium: true, accountIsPremium: false), "master off app icons")
check(!JerkgramAppIconAccess.isLocked(iconIsPremium: true, accountIsPremium: true), "entitled native premium preserved")
JerkgramLocalPremiumPolicy.update(masterEnabled: true)
check(sa.snapshot.emojiUnlocked && sa.snapshot.colorsUnlocked, "master on appearance capabilities")
check(projected(sa, a.postbox.user).emojiStatus != nil, "native projection local status")
check(JerkgramDownloadBoostSettings.mode(accountPeerId: a.peerId.toInt64()) == .maximum, "selected boost restored")
check(JerkgramSponsoredContentPolicy.removeSponsored(accountPeerId: a.peerId.toInt64()), "no ads effective")
check(JerkgramTranslationSettings.enabled(accountPeerId: a.peerId.toInt64()), "translation effective")
check(JerkgramLocalPremiumPolicy.savedTagsEnabled(accountPeerId: a.peerId.toInt64()), "tags effective")
check(!JerkgramAppIconAccess.isLocked(iconIsPremium: true, accountIsPremium: false), "app icon unlock")
let picker = PickerHarness(sa, local: true, selection: 77)
check(picker.run(TelegramMediaFile(88), 1100), "native picker timer handled locally")
check(sa.snapshot.settings.emojiFileId == 88 && sa.snapshot.settings.emojiExpiration == 1100, "native timer saved")
let stale = PickerHarness(sa, local: true)
JerkgramLocalPremiumPolicy.update(masterEnabled: false)
check(stale.run(TelegramMediaFile(99), nil), "revoked picker consumed without native fallback")
JerkgramLocalPremiumPolicy.update(masterEnabled: true)
check(stale.run(TelegramMediaFile(99), nil) && sa.snapshot.settings.emojiFileId == 88, "OFF ON rejects stale callback")
let disabled = PickerHarness(sa, local: true)
check(sa.update { $0.emojiEnabled = false }, "individual emoji off")
check(disabled.run(TelegramMediaFile(99), nil), "individual revocation consumed")
check(sa.update { $0.emojiEnabled = true }, "individual emoji on")
check(disabled.run(TelegramMediaFile(99), nil) && sa.snapshot.settings.emojiFileId == 88, "individual OFF ON rejects callback")
let native = PickerHarness(sa, local: false)
check(!native.run(TelegramMediaFile(99), nil), "ordinary native route unchanged")
let switchStale = PickerHarness(sa, local: true)
sa.setActive(false); sb.setActive(true)
check(projected(sb, b.postbox.user).emojiStatus == nil && projected(sb, a.postbox.user).emojiStatus == nil, "B cannot inherit A or foreign peer")
sb.setActive(false); sa.setActive(true)
check(switchStale.run(TelegramMediaFile(99), nil) && sa.snapshot.settings.emojiFileId == 88, "A B A fences callback")
sa.setActive(false); sx.setActive(true)
check(!sx.snapshot.eligible && !sx.update { $0.emojiEnabled = true; $0.emojiFileId = 99 }, "bot cannot acquire appearance")
check(projected(sx, bot.postbox.user).emojiStatus == nil, "bot native projection")
sx.setActive(false); sa.setActive(true)
check(projected(sa, TelegramUser(a.peerId.raw, bot: true)).emojiStatus == nil, "matching-ID displayed bot rejected")
check(!sa.snapshot.settings.permits(recordId: b.id.int64, ownPeerId: a.peerId.toInt64(), testing: false, active: true, ownIsBot: false, displayedPeerId: a.peerId.toInt64(), displayedIsBot: false), "record identity")
check(!sa.snapshot.settings.permits(recordId: a.id.int64, ownPeerId: a.peerId.toInt64(), testing: true, active: true, ownIsBot: false, displayedPeerId: a.peerId.toInt64(), displayedIsBot: false), "test environment identity")
JerkgramDownloadBoostSettings.update(accountPeerId: a.peerId.toInt64(), rawValue: "off")
JerkgramSponsoredContentPolicy.update(accountPeerId: a.peerId.toInt64(), enabled: false)
check(JerkgramDownloadBoostSettings.mode(accountPeerId: a.peerId.toInt64()) == .off && !JerkgramSponsoredContentPolicy.removeSponsored(accountPeerId: a.peerId.toInt64()), "master on individuals off")
let stock = JerkgramDownloadBoostPolicy.parameters(mode: .off, size: 20_000_000, isStory: false, fastDownloads: false, encrypted: false)
let boost = JerkgramDownloadBoostPolicy.parameters(mode: .maximum, size: 20_000_000, isStory: false, fastDownloads: false, encrypted: false)
check(stock.partSize == 128 * 1024 && stock.maxPendingParts == 6 && boost.partSize == 1024 * 1024 && boost.maxPendingParts == 12, "actual scheduler policy")
check(sa.snapshot.settings.owner == saved.owner && sa.snapshot.settings.profileColor == saved.profileColor, "master transitions preserve individual record")
check(a.postbox.user.emojiStatus == nil && a.postbox.user.profileColor == nil, "server peer never mutated")
print("Stable182 Premium policy, native picker routing and actual appearance store matrix passed")
